        public static UnitConverterVolumeFlowUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterVolumeFlowUnit>();
            for (int i = 0; i < 75; i++) if (GetUnitSystem((UnitConverterVolumeFlowUnit)i) == system) units.Add((UnitConverterVolumeFlowUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterVolumeFlowUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterVolumeFlowUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterVolumeFlowUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterVolumeFlowUnit)id : default(UnitConverterVolumeFlowUnit); return success;
        }

        public static UnitConverterVolumeFlowUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterVolumeFlowUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous VolumeFlow unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterVolumeFlowValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterVolumeFlowValue(value, (UnitConverterVolumeFlowUnit)id) : default(UnitConverterVolumeFlowValue); return success;
        }

        public static UnitConverterVolumeFlowValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterVolumeFlowValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous VolumeFlow unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterVolumeFlowUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


